    "Pattern micro-textured surface using soft lithography with PDMS molds",
    "Deposit TiO2/SiO2 photonic crystal arrays via nano-imprint lithography or atomic layer deposition",
    "Integrate PVA microcapillary network using microfluidic channel molding",
    "Embed hydrogel reservoirs via 3D printing or layer-by-layer deposition",
    "Apply surface treatments to create hydrophobic/hydrophilic zones via plasma or chemical grafting",
    "Assemble multi-layer stack with encapsulation for environmental protection"
  ],
  "quick_physics_check": [
    {
      "quantity": "Surface tension modulation range",
      "equation": "Δγ = γ_hydrophobic - γ_hydrophilic",
      "estimate": 0.025,
      "unit": "N/m",
      "requirement": "≥ 0.02 N/m for effective wettability switching"
    },
    {
      "quantity": "Structural color shift bandwidth",
      "equation": "Δλ = λ_max - λ_min",
      "estimate": 150,
      "unit": "nm",
      "requirement": "≥ 100 nm for visible spectrum coverage"
