{
  "title": "Hydrophobic Micro-Textured Self-Cleaning Surface with Embedded Electrostatic Dust Repellent",
  "summary": "This concept integrates a nanostructured hydrophobic surface with embedded electrostatic actuators to actively repel dust and pollutants. When activated, the surface generates a controlled electrostatic field that lifts particulates, while water beads and rolls off, carrying away residues. The system is energy-efficient, requires minimal maintenance, and can be retrofitted onto building facades and vehicle exteriors.",
  "bio_to_engineering_mapping": [
    {
      "biological_feature": "Lotus leaf's superhydrophobicity",
      "engineering_feature": "Micro-pillar array with nano-scale roughness and low-surface-energy coating",
      "scale_change": "Micron-to-nano scale replication"
    },
    {
      "biological_feature": "Gecko's electrostatic adhesion control",
      "engineering_feature": "Embedded micro-electrodes for localized electrostatic repulsion",
      "scale_change": "Micro-scale electrode array"
    },
    {
      "biological_feature": "Bird feathers' self-cleaning via vibration",
      "engineering_feature": "Pulsed electrostatic field to induce particle vibration and detachment",
